# Purpose: File-backed job persistence, metadata updates, and artefact storage.
# Key Inputs: Job parameters, uploaded files, computed results.
# Key Outputs: Job envelopes, persisted payloads, local artefact files.
# Dependency Notes: filesystem operations, JSON serialization, TTL cleanup logic.
